WITH ranked AS (SELECT * FROM promotions QUALIFY ROW_NUMBER() OVER (PARTITION BY channel ORDER BY ends_on DESC, id) = 1) SELECT CASE WHEN discount_pct >= 0.29 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, promo_code, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, MAX(discount_pct) FILTER (WHERE promo_code = 'SPRING10') AS spring10_max_discount_pct, COUNT(DISTINCT promo_code) AS distinct_promo_codes, PERCENT_RANK() OVER (PARTITION BY CASE WHEN discount_pct >= 0.29 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY MAX(discount_pct) FILTER (WHERE promo_code = 'SPRING10') DESC) AS spring10_max_discount_pct_percent_rank FROM ranked GROUP BY discount_pct_tier, promo_code
